280      if (node.type === 'image') return renderImageNode(node);
281      if (node.type === 'attachment') return renderAttachmentNode(node);
282      if (node.type === 'lineBreak') return '<br>';
283      if (node.type === 'pageBreak') return '<span class="msdoc-page-break"></span>';
284      return '';
